import React from 'react';

function colorOf(statusCode) {
  if (statusCode === 'DANGER') return '#ef4444';
  if (statusCode === 'WARNING') return '#eab308';
  return '#22c55e';
}

export default function ProtectionStatusBadge({
  protectionStatus = '안전',
  statusCode = 'SAFE',
  lastEventTime = 'N/A',
  summaryLoading = false,
  summaryError = null,
}) {
  return (
    <div className="status-panel">
      <div className="panel-header">
        <h2>실시간 보호 상태</h2>
      </div>

      <div className="status-body">
        <div className="status-left">
          <div className="status-dot" style={{ backgroundColor: colorOf(statusCode) }} />
          <span className="status-text">{protectionStatus}</span>
        </div>

        <div className="status-right" style={{ fontSize: 12, color: '#9ca3af' }}>
          <div>최근 이벤트 시각: {lastEventTime}</div>
          {summaryLoading && <div>요약 불러오는 중...</div>}
          {summaryError && <div style={{ color: 'red' }}>요약 실패: {summaryError.message}</div>}
        </div>
      </div>
    </div>
  );
}
